from pathlib import Path
import sys,html,json
root=Path(__file__).resolve().parent.parent
sys.path.insert(0,str(root/'work'/'docs-runtime'))
import markdown
version=json.loads((root/'package.json').read_text())['version']
css='''*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:24px}body{font:15px/1.8 Inter,"Segoe UI",Arial,sans-serif;margin:0;background:#f3f6fa;color:#203249}header{background:#132d39;color:#fff;padding:40px max(5vw,24px)}header .brand{font-size:11px;letter-spacing:2px;color:#a9dbcd}header h1{font-size:clamp(28px,4vw,43px);letter-spacing:-1.3px;line-height:1.2;margin:16px 0}header p{color:#acc3cd;font-size:13px}.guide-layout{max-width:1390px;margin:28px auto;display:grid;grid-template-columns:255px minmax(0,1fr);gap:24px;padding:0 22px}main{padding:36px 42px;background:#fff;border:1px solid #dfe6ef;border-radius:16px;min-width:0}.doc-nav{position:sticky;top:24px;align-self:start;max-height:90dvh;overflow:auto;padding:10px 0 20px}.doc-nav .nav-title{font-size:10px;letter-spacing:1.5px;color:#798a9e;padding:0 12px}.doc-nav a{display:block;font-size:11px;padding:7px 12px;border-radius:7px;color:#566a80;line-height:1.6}.doc-nav a:hover{color:#176b73;background:#e4f0ed;text-decoration:none}h1{font-size:28px;letter-spacing:-.8px;line-height:1.35}h2{font-size:21px;letter-spacing:-.5px;margin-top:44px;padding-top:18px;border-top:1px solid #e2e9f0;color:#1e4f5d;line-height:1.4}h3{color:#285a69}a{color:#176b73;text-decoration:none}a:hover{text-decoration:underline}pre{padding:18px 20px;background:#132d39;color:#e2f4ee;border-radius:10px;overflow:auto;font-size:12px;line-height:1.8}code{overflow-wrap:anywhere}p code,li code,td code{background:#edf3f6;padding:2px 4px;border-radius:4px;font-size:12px}table{border-collapse:collapse;width:100%;margin:22px 0;font-size:12px}th,td{border:1px solid #dce5ee;text-align:left;padding:13px;vertical-align:top}th{background:#eff6f7;color:#31596a;font-size:11px}li{margin-bottom:10px}section+section{margin-top:55px;padding-top:22px;border-top:2px solid #d3e6e5}footer{padding:24px;text-align:center;color:#8392a5;font-size:11px}@media(max-width:850px){.guide-layout{display:block;padding:0 12px;margin:15px auto}.doc-nav{position:static;max-height:230px;margin-bottom:18px;padding:15px;border:1px solid #dfe6ef;background:#fff;border-radius:12px}main{padding:24px 20px}table{display:block;overflow:auto}header{padding:28px 24px}}@media print{body{background:white}.doc-nav{display:none}.guide-layout{display:block;margin:0;padding:0}header{background:white;color:#132d39;padding:10px}header p,header .brand{color:#5d7182}main{border:0;margin:0;padding:0}pre{white-space:pre-wrap;color:#132d39;background:#eee}h2{break-after:avoid}table{font-size:10px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}'''
quick=markdown.markdown((root/'docs/QUICKSTART.md').read_text(encoding='utf-8'),extensions=['tables','fenced_code','toc'])
renderer=markdown.Markdown(extensions=['tables','fenced_code','toc'])
complete=renderer.convert((root/'docs/COMPLETE-GUIDE.md').read_text(encoding='utf-8'))
links=['<a href="#quickstart">Quick start</a>']
def visit(tokens):
    for token in tokens:
        if token['level']==2:links.append('<a href="#'+html.escape(token['id'],quote=True)+'">'+html.escape(token['name'])+'</a>')
        visit(token.get('children',[]))
visit(renderer.toc_tokens)
document='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PARMTECH Connector · Setup and User Guide</title><style>'+css+'</style></head><body><header><p class="brand">PARMTECH / HOSTING CONNECTOR</p><h1>Setup, Login &amp; Complete User Guide</h1><p>Version '+html.escape(version)+' · English · Self-hosting handbook</p></header><div class="guide-layout"><nav class="doc-nav" aria-label="Documentation contents"><p class="nav-title">IN THIS GUIDE</p>'+''.join(links)+'</nav><main><section id="quickstart">'+quick+'</section><section id="complete-guide">'+complete+'</section></main></div><footer>PARMTECH · Source package documentation · No credentials included</footer></body></html>'
(root/'docs'/'START-HERE.html').write_text(document,encoding='utf-8')
print('Rendered the English documentation handbook.')
